import re
from sage.all import *

# Define the curve parameters
p = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
K = GF(p)
a = K(0)
b = K(7)
E = EllipticCurve(K, [a, b])

def point_double(x, y):
    # Point doubling formula for secp256k1
    if y == 0:
        return None

    # s = (3x^2) / (2y)
    s = (3 * x * x) * pow(2 * y, -1, p) % p

    # x_r = s^2 - 2x
    x_r = (s * s - 2 * x) % p

    # y_r = s(x - x_r) - y
    y_r = (s * (x - x_r) - y) % p

    return x_r

def point_double_from_xy(x_hex, y_hex):
    try:
        # Convert hex strings to integers
        x = int(x_hex, 16)
        y = int(y_hex, 16)

        # Verify point is on curve
        if (pow(y, 2, p) - (pow(x, 3, p) + 7)) % p != 0:
            print("Point not on curve!")
            return None

        result = point_double(x, y)
        if result is None:
            return None

        # Return x coordinate as 64-character hex string
        return hex(result)[2:].zfill(64)
    except Exception as e:
        print(f"Error in point_double: {str(e)}")
        return None

