    try:
        # Use regex to extract coordinates
        match = re.search(r'\(\s*([a-fA-F0-9]+)\s*,\s*([a-fA-F0-9]+)\s*\)', data)
        if match:
            return match.group(1).strip(), match.group(2).strip()
        return None, None
    except Exception as e:
        print(f"Error extracting coordinates: {str(e)}")
        return None, None

