import re
from sage.all import *

def setup_curve():
    # Define the curve parameters for secp256k1
    p = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
    F = GF(p)
    E = EllipticCurve(F, [0, 7])  # y^2 = x^3 + 7
    return E

def point_double(E, x, y):
    try:
        # Create point on curve
        P = E(x, y)
        # Double the point
        Q = 2 * P
        # Return x-coordinate
        return int(Q[0])
    except Exception as e:
        print(f"Error in point doubling: {e}")
        return None

def extract_coordinates(data):
    try:
        # Extract coordinates using regex
        match = re.search(r'\(\s*([a-fA-F0-9]+)\s*,\s*([a-fA-F0-9]+)\s*\)', data)
        if match:
            x = int(match.group(1), 16)
            y = int(match.group(2), 16)
            return x, y
        return None, None
    except Exception as e:
        print(f"Error extracting coordinates: {e}")
        return None, None

