from pwn import *
import re
from sage.all import *

# secp256k1 curve parameters
p = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
F = GF(p)
E = EllipticCurve(F, [0, 7])  # y^2 = x^3 + 7

def extract_coords(data):
    """Extract coordinates from server response"""
    try:
        lines = data.split('\n')
        for line in lines:
            if '(' in line and ')' in line:
                coords = line.strip()
                coords = coords.replace('(', '').replace(')', '').replace(' ', '')
                x, y = coords.split(',')
                return int(x, 16), int(y, 16)
    except Exception as e:
        print(f"Error extracting coordinates: {e}")
    return None, None

def main():
    context.log_level = 'debug'
    while True:
        try:
            # Connect to server
            conn = remote('crypto.chal.csaw.io', 5000)

            while True:
                try:
                    # Get data until "Guess?"
                    data = conn.recvuntil(b'Guess? ', timeout=5).decode()
                    print(f"Server data: {data}")

                    if 'flag{' in data:
                        print(f"Found flag: {data}")
                        conn.close()
                        return

                    # Extract coordinates
                    x, y = extract_coords(data)
                    if x is None or y is None:
                        print("Failed to extract coordinates")
                        continue

                    # Create point and double it
                    try:
                        P = E(x, y)
                        Q = 2 * P
                        result = hex(int(Q[0]))[2:].zfill(64)
                        print(f"Sending result: {result}")
                        conn.sendline(result.encode())

                        # Get response
                        resp = conn.recvline(timeout=5)
                        print(f"Server response: {resp}")

                    except Exception as e:
                        print(f"Error in point operations: {e}")
                        continue

                except EOFError:
                    raise
                except Exception as e:
                    print(f"Error in communication: {e}")
                    raise

        except Exception as e:
            print(f"Connection error: {e}")
            try:
                conn.close()
            except:
